using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Globalization;
using System.IO;
using System.Runtime.InteropServices;
using System.Text;
using System.Threading;
namespace DjiMicKey {
    static class SelfTests {
        static int passed; static StringBuilder report;
        static void Check(bool result,string name){if(!result)throw new Exception("FAIL: "+name);passed++;report.AppendLine("PASS: "+name);}
        public static int Run(string path){report=new StringBuilder();try{
            Check(IntPtr.Size==8,"64-bit process");Check(Marshal.SizeOf(typeof(Native.Input))==40,"SendInput ABI is 40 bytes");
            Check(Marshal.SizeOf(typeof(Native.Kbd))==24,"keyboard hook ABI is 24 bytes");Check(Marshal.SizeOf(typeof(PropVariant))==24,"PROPVARIANT ABI is 24 bytes");
            ShortcutSpec spec=new ShortcutSpec();Native.Input[] input=spec.BuildInput();Check(input.Length==6,"default shortcut has three presses and three releases");
            Check(input[0].data.keyboard.vk==0xA2&&input[1].data.keyboard.vk==0xA4&&input[2].data.keyboard.vk==0x78,"default is left Ctrl + left Alt + F9");
            Check(input[3].data.keyboard.vk==0x78&&input[4].data.keyboard.vk==0xA4&&input[5].data.keyboard.vk==0xA2,"release keys in reverse order");
            Check((input[0].data.keyboard.flags&2)==0&&(input[5].data.keyboard.flags&2)==2,"press / release flags");
            spec=new ShortcutSpec{Ctrl=false,Alt=false,Key="RCtrl"};input=spec.BuildInput();Check(input.Length==2&&(input[0].data.keyboard.flags&1)==1,"right Ctrl uses extended-key flag");
            bool invalid=false;try{new ShortcutSpec{Key="RCtrl",Ctrl=true}.Validate();}catch(ArgumentException){invalid=true;}Check(invalid,"reject duplicated modifier");
            invalid=false;try{new ShortcutSpec{Key="Volume_Up"}.Validate();}catch(ArgumentException){invalid=true;}Check(invalid,"reject source key as target and unknown tokens");
            MappingGate gate=new MappingGate();GateResult r=gate.Process(true,true,0);Check(r.Suppress&&!r.Trigger,"suppress physical press without firing early");
            r=gate.Process(true,true,20);Check(r.Suppress&&!r.Trigger,"suppress held-key auto repeat");r=gate.Process(false,true,40);Check(r.Suppress&&r.Trigger,"one release produces one trigger");
            r=gate.Process(false,true,50);Check(!r.Suppress&&!r.Trigger,"orphan release does not trigger");gate.Process(true,true,100);r=gate.Process(false,true,110);Check(r.Suppress&&!r.Trigger,"debounce suppresses rapid bounce");
            gate.Process(true,true,400);r=gate.Process(false,true,410);Check(r.Trigger,"next deliberate short press works");
            gate=new MappingGate();r=gate.Process(true,false,0);Check(!r.Suppress,"disabled / disconnected keys pass through");r=gate.Process(false,true,10);Check(!r.Suppress&&!r.Trigger,"connection during a press cannot create orphan trigger");
            gate.Process(true,true,500);r=gate.Process(false,false,510);Check(r.Suppress&&!r.Trigger,"disconnect cancels pending trigger while balancing release");
            string dir=Path.Combine(Path.GetTempPath(),"DJIMicKey-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);string config=Path.Combine(dir,"settings.ini");
            try{Settings s=new Settings();s.Shortcut=new ShortcutSpec{Ctrl=false,Alt=true,Shift=true,Win=false,Key="F24"};s.Enabled=false;s.Save(config);Settings loaded=Settings.Load(config);Check(!loaded.Enabled&&loaded.Shortcut.Key=="F24"&&loaded.Shortcut.Alt&&loaded.Shortcut.Shift&&!loaded.Shortcut.Ctrl,"config round trip");s.Save(config);Check(Settings.Load(config).Shortcut.Key=="F24","atomic settings replacement");File.WriteAllText(config,"Key=NoSuchKey");invalid=false;try{Settings.Load(config);}catch(ArgumentException){invalid=true;}Check(invalid,"invalid persisted shortcut is rejected");}finally{if(File.Exists(config))File.Delete(config);if(File.Exists(config+".tmp"))File.Delete(config+".tmp");Directory.Delete(dir);}
            using(KeyboardMapper mapper=new KeyboardMapper()){Check(true,"native keyboard hook install and dispose");}
            List<Native.Kbd> observed=new List<Native.Kbd>();
            Native.HookProc probe=delegate(int code,IntPtr message,IntPtr data){if(code>=0){Native.Kbd k=(Native.Kbd)Marshal.PtrToStructure(data,typeof(Native.Kbd));if(k.extra==Native.Marker){observed.Add(k);return new IntPtr(1);}}return Native.CallNextHookEx(IntPtr.Zero,code,message,data);};
            IntPtr probeHook=Native.SetWindowsHookEx(13,probe,Native.GetModuleHandle(null),0);
            if(probeHook==IntPtr.Zero)throw new System.ComponentModel.Win32Exception();
            try{new ShortcutSpec().Send();Stopwatch wait=Stopwatch.StartNew();while(observed.Count<6&&wait.ElapsedMilliseconds<1000){System.Windows.Forms.Application.DoEvents();Thread.Sleep(5);}Check(observed.Count==6,"real SendInput events reach the native hook (consumed by test hook)");Check(observed[0].vk==0xA2&&observed[1].vk==0xA4&&observed[2].vk==0x78,"native observed modifier sides and target are correct");Check((observed[0].flags&0x10)!=0&&(observed[5].flags&0x80)!=0,"native injected and release flags are correct");}finally{Native.UnhookWindowsHookEx(probeHook);GC.KeepAlive(probe);}
            Check(!KeyboardMapper.IsOwnEvent(new Native.Kbd{vk=0xAF,flags=0x11,extra=UIntPtr.Zero}),"DJI Windows-injected media press is accepted");
            Check(!KeyboardMapper.IsOwnEvent(new Native.Kbd{vk=0xAF,flags=0x91,extra=UIntPtr.Zero}),"DJI Windows-injected media release is accepted");
            Check(KeyboardMapper.IsOwnEvent(new Native.Kbd{vk=0xAF,extra=Native.Marker}),"only this tool's own marker is ignored");
            ShortcutRecorder recorder=new ShortcutRecorder();recorder.Process(0xA3,true);recorder.Process(0xA5,true);recorder.Process(0x20,true);recorder.Process(0x20,false);recorder.Process(0xA5,false);Check(!recorder.Complete,"recorder waits for all held modifiers to release");recorder.Process(0xA3,false);Check(recorder.Complete&&recorder.Result.Display=="右 Ctrl + 右 Alt + 空格","recorder preserves right-hand modifier sides");
            recorder=new ShortcutRecorder();recorder.Process(0x78,true);recorder.Process(0x78,true);recorder.Process(0x78,false);Check(recorder.Complete&&recorder.Result.VirtualKeys().Count==1,"single key capture ignores auto repeat");
            recorder=new ShortcutRecorder();recorder.Process(0xA3,true);recorder.Process(0xA3,false);Check(recorder.Result.Display=="右 Ctrl","standalone modifier capture");
            recorder=new ShortcutRecorder();recorder.Process(0x1B,true);Check(recorder.Cancelled,"Escape cancels capture");
            recorder=new ShortcutRecorder();recorder.Process(0xAF,true);recorder.Process(0xAF,false);Check(recorder.Complete&&recorder.Result==null&&recorder.Error.Length>0,"source volume-up cannot be recorded as target");
            recorder=new ShortcutRecorder();recorder.Process(0x41,true);recorder.Process(0x42,true);recorder.Process(0x41,false);recorder.Process(0x42,false);Check(recorder.Result==null&&recorder.Error.Length>0,"two ordinary keys are rejected clearly");
            Check(ShortcutSpec.Normalize(0x11,0x1D,1)==0xA3&&ShortcutSpec.Normalize(0x10,0x36,0)==0xA1,"generic modifier events normalize to the correct side");
            string chordDir=Path.Combine(Path.GetTempPath(),"DJIMicKey-chord-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(chordDir);string chordFile=Path.Combine(chordDir,"settings.ini");try{Settings chord=new Settings();chord.Shortcut=ShortcutSpec.FromKeys(new ushort[]{0xA3,0xA5,0x20});chord.Save(chordFile);Check(Settings.Load(chordFile).Shortcut.Display=="右 Ctrl + 右 Alt + 空格","recorded chord persists with modifier sides");}finally{if(File.Exists(chordFile))File.Delete(chordFile);Directory.Delete(chordDir);}
            int sourceHits=0,escapedSource=0;Native.HookProc safety=delegate(int code,IntPtr message,IntPtr data){if(code>=0){Native.Kbd key=(Native.Kbd)Marshal.PtrToStructure(data,typeof(Native.Kbd));if(key.vk==0xAF){escapedSource++;return new IntPtr(1);}}return Native.CallNextHookEx(IntPtr.Zero,code,message,data);};IntPtr safetyHook=Native.SetWindowsHookEx(13,safety,Native.GetModuleHandle(null),0);if(safetyHook==IntPtr.Zero)throw new Exception("Safety hook failed");try{using(KeyboardMapper mapper=new KeyboardMapper()){mapper.Enabled=true;mapper.Connected=true;mapper.Pressed+=delegate{Interlocked.Increment(ref sourceHits);};Native.Input down=new Native.Input();down.type=1;down.data.keyboard=new Native.KeyboardInput{vk=0xAF,scan=0,flags=1,extra=UIntPtr.Zero};Native.Input up=down;up.data.keyboard.flags=3;Check(Native.SendInput(2,new Native.Input[]{down,up},Marshal.SizeOf(typeof(Native.Input)))==2,"inject DJI-like media events into Windows");Stopwatch waitSource=Stopwatch.StartNew();while(sourceHits==0&&waitSource.ElapsedMilliseconds<1500){System.Windows.Forms.Application.DoEvents();Thread.Sleep(5);}Check(sourceHits==1&&escapedSource==0,"DJI-like injected source is suppressed and triggers once on dedicated thread");}}finally{Native.UnhookWindowsHookEx(safetyHook);GC.KeepAlive(safety);}
            string preferencesDir=Path.Combine(Path.GetTempPath(),"DJIMicKey-display-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(preferencesDir);string preferencesFile=Path.Combine(preferencesDir,"settings.ini");try{Settings preferences=new Settings();preferences.CompatibilityMode=true;preferences.Shortcut=ShortcutSpec.FromKeys(new ushort[]{0xA3,0xA5,0x20});preferences.Save(preferencesFile);Settings loaded=Settings.Load(preferencesFile);Check(loaded.CompatibilityMode&&loaded.Shortcut.Display==preferences.Shortcut.Display,"compatibility mode persists without changing the chord");File.WriteAllText(preferencesFile,"Key=F9\r\nCtrl=1\r\nAlt=1\r\nEnabled=1\r\n");Check(Settings.Load(preferencesFile).CompatibilityMode,"legacy settings migrate with compatibility enabled by default");}finally{if(File.Exists(preferencesFile))File.Delete(preferencesFile);Directory.Delete(preferencesDir);}
            string command=StartupRegistration.Command(@"C:\Program Files\大疆工具\DJIMicKey.exe");Check(command=="\"C:\\Program Files\\大疆工具\\DJIMicKey.exe\" --autostart","startup command quotes spaces and Unicode path");bool invalidStartup=false;try{StartupRegistration.Command("C:\\invalid\"path\\a.exe");}catch(ArgumentException){invalidStartup=true;}Check(invalidStartup,"startup rejects invalid quoted paths");
            string registryTest=@"Software\DJIMicKey\Tests\"+Guid.NewGuid().ToString("N");try{using(Microsoft.Win32.RegistryKey key=Microsoft.Win32.Registry.CurrentUser.CreateSubKey(registryTest))key.SetValue("Unrelated","keep");StartupRegistration.Write(registryTest,"DJIMicKey",true,System.Windows.Forms.Application.ExecutablePath);Check(StartupRegistration.Matches(registryTest,"DJIMicKey",System.Windows.Forms.Application.ExecutablePath),"startup registration enable and read back in isolated key");StartupRegistration.Write(registryTest,"DJIMicKey",false,System.Windows.Forms.Application.ExecutablePath);Check(!StartupRegistration.Matches(registryTest,"DJIMicKey",System.Windows.Forms.Application.ExecutablePath),"startup registration disable");using(Microsoft.Win32.RegistryKey key=Microsoft.Win32.Registry.CurrentUser.OpenSubKey(registryTest))Check((string)key.GetValue("Unrelated")=="keep","startup disable preserves unrelated values");}finally{Microsoft.Win32.Registry.CurrentUser.DeleteSubKeyTree(registryTest,false);}
            Check(InputTrace.IsMedia(0xAF)&&InputTrace.IsMedia(0x5E)&&!InputTrace.IsMedia(0x41)&&!InputTrace.IsMedia(0x0D),"diagnostic filtering excludes ordinary character keys");
            Check(InputTrace.AppCommand(new IntPtr(10L<<16))==10&&InputTrace.AppCommandDevice(new IntPtr(0x400000))==0x40&&InputTrace.AppCommandKeyState(new IntPtr(5))==5,"Windows multimedia command fields are decoded correctly");
            InputTrace trace=new InputTrace();int streamed=0;trace.Entry+=delegate{streamed++;};trace.Add("inactive");trace.Start();for(int i=0;i<300;i++)trace.Add("entry-"+i);Check(streamed==300,"diagnostic events stream to the UI while capture is active");string traceText=trace.Stop();Check(trace.Dropped==44&&traceText.IndexOf("entry-299",StringComparison.Ordinal)>=0&&traceText.IndexOf("entry-0"+Environment.NewLine,StringComparison.Ordinal)<0,"diagnostic buffer is bounded and reports dropped entries");trace.Add("after-stop");Check(trace.Stop().IndexOf("after-stop",StringComparison.Ordinal)<0,"diagnostic capture stops explicitly");trace.Start();trace.Add("restart");Check(trace.Stop().IndexOf("entry-",StringComparison.Ordinal)<0,"new diagnosis resets old capture");
            using(KeyboardMapper healthMapper=new KeyboardMapper()){Check(healthMapper.IsRunning&&healthMapper.ProbeHealth(),"listener health probe is acknowledged and consumed by its native hook");}
            trace.Start();trace.Add("LOWLEVEL media checkpoint");for(int i=0;i<300;i++)trace.Add("RAW packet="+i);Check(trace.Stop().IndexOf("LOWLEVEL media checkpoint",StringComparison.Ordinal)>=0,"raw report bursts preserve key diagnostic decisions");
            DeviceState noAudio=new DeviceState{Hid=true};Check(noAudio.ButtonReady&&!noAudio.Connected,"button mapping readiness is independent of the audio endpoint");
            report.AppendLine("TOTAL: "+passed+" passed");File.WriteAllText(path,report.ToString(),Encoding.UTF8);return 0;
        }catch(Exception ex){report.AppendLine(ex.ToString());File.WriteAllText(path,report.ToString(),Encoding.UTF8);return 1;}}
    }
    static class Diagnostics {
        public static int Run(string path){StringBuilder report=new StringBuilder();try{
            report.AppendLine("DJI Mic Key diagnostics");report.AppendLine("UTC: "+DateTime.UtcNow.ToString("o"));
            DeviceState device=DeviceProbe.Scan();report.AppendLine("DJI USB HID: "+device.Hid);report.AppendLine("Matching capture endpoint: "+device.Name);report.AppendLine("Ready: "+device.Connected);if(device.Error.Length>0)report.AppendLine("Probe error: "+device.Error);
            if(device.Connected){float peak=0;using(AudioMonitor monitor=new AudioMonitor(device.EndpointId)){for(int i=0;i<15;i++){Thread.Sleep(80);peak=Math.Max(peak,monitor.Poll());}}report.AppendLine("WASAPI shared capture / meter: OK");report.AppendLine("Peak sample: "+peak.ToString("0.000000",CultureInfo.InvariantCulture));}
            report.AppendLine("Working set MiB: "+(Process.GetCurrentProcess().WorkingSet64/1048576.0).ToString("0.0",CultureInfo.InvariantCulture));File.WriteAllText(path,report.ToString(),Encoding.UTF8);return device.Connected?0:2;
        }catch(Exception ex){report.AppendLine(ex.ToString());File.WriteAllText(path,report.ToString(),Encoding.UTF8);return 1;}}
    }
}
